using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using Moq;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Department CreateTestDepartment(string name = "Engineering")
    {
        var dept = new Department
        {
            Name = name,
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();
        return dept;
    }

    private Course CreateTestCourse(string title = "Chemistry", int courseId = 1001, int? departmentId = null)
    {
        var dept = departmentId.HasValue
            ? _context.Departments.Find(departmentId.Value)
            : CreateTestDepartment();

        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = dept!.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    #region Index Tests

    [Fact]
    public void Index_ReturnsViewWithCourseList()
    {
        // Arrange
        CreateTestCourse("Chemistry", 1001);
        CreateTestCourse("Physics", 1002);

        // Act
        var result = _controller.Index();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_EmptyDatabase_ReturnsEmptyList()
    {
        // Act
        var result = _controller.Index();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
        Assert.Empty(model);
    }

    #endregion

    #region Details Tests

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        // Arrange
        var course = CreateTestCourse("Chemistry", 2001);

        // Act
        var result = _controller.Details(course.CourseID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Chemistry", model.Title);
        Assert.Equal(3, model.Credits);
    }

    #endregion

    #region Create Tests

    [Fact]
    public void Create_Get_ReturnsViewWithEmptyCourse()
    {
        // Arrange
        CreateTestDepartment();

        // Act
        var result = _controller.Create();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.IsType<Course>(viewResult.Model);
    }

    [Fact]
    public void Create_Post_ValidCourse_RedirectsToIndex()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = 3001,
            Title = "New Course",
            Credits = 4,
            DepartmentID = dept.DepartmentID
        };

        // Act
        var result = _controller.Create(course, null!);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Create_Post_ValidCourse_SavesToDB()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = new Course
        {
            CourseID = 3002,
            Title = "Saved Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        // Act
        _controller.Create(course, null!);

        // Assert
        var saved = _context.Courses.Find(3002);
        Assert.NotNull(saved);
        Assert.Equal("Saved Course", saved.Title);
        Assert.Equal(3, saved.Credits);
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = new Course { CourseID = 3003, DepartmentID = dept.DepartmentID };
        _controller.ModelState.AddModelError("Title", "Required");

        // Act
        var result = _controller.Create(course, null!);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(course, viewResult.Model);
    }

    #endregion

    #region Edit Tests

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Edit(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Edit(9999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCourse()
    {
        // Arrange
        var course = CreateTestCourse("Editable Course", 4001);

        // Act
        var result = _controller.Edit(course.CourseID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Editable Course", model.Title);
    }

    [Fact]
    public void Edit_Post_ValidCourse_RedirectsToIndex()
    {
        // Arrange
        var course = CreateTestCourse("Original", 4002);
        _context.Entry(course).State = EntityState.Detached;

        var updatedCourse = new Course
        {
            CourseID = 4002,
            Title = "Updated",
            Credits = 4,
            DepartmentID = course.DepartmentID
        };

        // Act
        var result = _controller.Edit(updatedCourse, null!);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModel_ReturnsView()
    {
        // Arrange
        var dept = CreateTestDepartment();
        var course = new Course { CourseID = 4003, DepartmentID = dept.DepartmentID };
        _controller.ModelState.AddModelError("Title", "Required");

        // Act
        var result = _controller.Edit(course, null!);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(course, viewResult.Model);
    }

    #endregion

    #region Delete Tests

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        // Arrange
        var course = CreateTestCourse("Deletable", 5001);

        // Act
        var result = _controller.Delete(course.CourseID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal("Deletable", model.Title);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
    {
        // Arrange
        var course = CreateTestCourse("ToDelete", 5002);

        // Act
        var result = _controller.DeleteConfirmed(course.CourseID);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Null(_context.Courses.Find(5002));
    }

    #endregion
}

