using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor CreateTestInstructor(string firstName = "John", string lastName = "Smith", DateTime? hireDate = null)
    {
        var instructor = new Instructor
        {
            FirstMidName = firstName,
            LastName = lastName,
            HireDate = hireDate ?? new DateTime(2010, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Course CreateTestCourse(string title = "Chemistry", int courseId = 1001)
    {
        var dept = new Department
        {
            Name = "Engineering",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1)
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    #region Index Tests

    [Fact]
    public void Index_NoParameters_ReturnsViewWithInstructorIndexData()
    {
        // Arrange
        CreateTestInstructor("Alice", "Smith");
        CreateTestInstructor("Bob", "Jones");

        // Act
        var result = _controller.Index(null, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");
        var course = CreateTestCourse("Chemistry", 2001);
        var assignment = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
        _context.CourseAssignments.Add(assignment);
        _context.SaveChanges();

        // Act
        var result = _controller.Index(instructor.ID, null);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
    }

    #endregion

    #region Details Tests

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Details(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Details(999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructor = CreateTestInstructor("Alice", "Smith");

        // Act
        var result = _controller.Details(instructor.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Alice", model.FirstMidName);
        Assert.Equal("Smith", model.LastName);
    }

    #endregion

    #region Create Tests

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        // Act
        var result = _controller.Create();

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.NotNull(model.CourseAssignments);
    }

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        var result = _controller.Create(instructor, null!);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
    }

    [Fact]
    public void Create_Post_ValidInstructor_SavesToDB()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "Saved",
            LastName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        _controller.Create(instructor, null!);

        // Assert
        var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "Instructor");
        Assert.NotNull(saved);
        Assert.Equal("Saved", saved.FirstMidName);
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AssignsCourses()
    {
        // Arrange
        var course = CreateTestCourse("Physics", 3001);
        var instructor = new Instructor
        {
            FirstMidName = "Course",
            LastName = "Assigner",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        // Act
        _controller.Create(instructor, new[] { course.CourseID.ToString() });

        // Assert
        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .FirstOrDefault(i => i.LastName == "Assigner");
        Assert.NotNull(saved);
        Assert.Single(saved.CourseAssignments);
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        // Arrange
        var instructor = new Instructor
        {
            FirstMidName = "Invalid",
            LastName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _controller.ModelState.AddModelError("LastName", "Required");

        // Act
        var result = _controller.Create(instructor, null!);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        Assert.Equal(instructor, viewResult.Model);
    }

    #endregion

    #region Delete Tests

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        // Act
        var result = _controller.Delete(null);

        // Assert
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        // Act
        var result = _controller.Delete(999);

        // Assert
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithInstructor()
    {
        // Arrange
        var instructor = CreateTestInstructor("Delete", "Me");

        // Act
        var result = _controller.Delete(instructor.ID);

        // Assert
        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal("Delete", model.FirstMidName);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
    {
        // Arrange
        var instructor = CreateTestInstructor("Delete", "Confirmed");

        // Act
        var result = _controller.DeleteConfirmed(instructor.ID);

        // Assert
        var redirectResult = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirectResult.ActionName);
        Assert.Null(_context.Instructors.Find(instructor.ID));
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDepartmentAdmin_NullsOutDepartmentAdministrator()
    {
        // Arrange
        var instructor = CreateTestInstructor("Admin", "Instructor");
        var dept = new Department
        {
            Name = "Dept With Admin",
            Budget = 100000,
            StartDate = new DateTime(2020, 1, 1),
            InstructorID = instructor.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        // Act
        _controller.DeleteConfirmed(instructor.ID);

        // Assert
        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.Null(updatedDept!.InstructorID);
    }

    #endregion
}

