using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new NotificationsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void GetNotifications_NoNotifications_ReturnsSuccessWithEmptyList()
    {
        // Drain any pre-existing notifications from static queue
        DrainNotifications();

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        Assert.NotNull(jsonResult.Value);

        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.NotNull(successProp);
        Assert.True((bool)successProp.GetValue(value)!);

        var countProp = value.GetType().GetProperty("count");
        Assert.NotNull(countProp);
        Assert.Equal(0, (int)countProp.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotificationsWithSuccess()
    {
        // Arrange - drain existing, then add one
        DrainNotifications();

        // Use a separate controller to generate a notification via the base class
        using var ctx2 = TestDbContextFactory.Create();
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2020, 1, 1)
        };
        ctx2.Students.Add(student);
        ctx2.SaveChanges();

        // Use the notification service directly
        var svc = new ContosoUniversity.Services.NotificationService();
        svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "TestUser");

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);

        var countProp = value.GetType().GetProperty("count");
        var count = (int)countProp!.GetValue(value)!;
        Assert.True(count >= 1);
    }

    [Fact]
    public void MarkAsRead_ValidId_ReturnsSuccess()
    {
        // Act
        var result = _controller.MarkAsRead(1);

        // Assert
        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
    }

    [Fact]
    public void Index_ReturnsView()
    {
        // Act
        var result = _controller.Index();

        // Assert
        Assert.IsType<ViewResult>(result);
    }

    private void DrainNotifications()
    {
        var svc = new ContosoUniversity.Services.NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }
}

