using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain any leftover notifications from other tests (static queue)
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        _service.Dispose();
    }

    [Fact]
    public void SendNotification_ValidData_EnqueuesNotification()
    {
        // Act
        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("John Doe", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesEntityIdInMessage()
    {
        // Act
        _service.SendNotification("Course", "42", EntityOperation.UPDATE, "System");

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
    }

    [Fact]
    public void SendNotification_CreateOperation_GeneratesCorrectMessage()
    {
        // Act
        _service.SendNotification("Student", "1", "Alice Smith", EntityOperation.CREATE);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("New Student 'Alice Smith' has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_UpdateOperation_GeneratesCorrectMessage()
    {
        // Act
        _service.SendNotification("Department", "5", "Engineering", EntityOperation.UPDATE);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department 'Engineering' has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
    {
        // Act
        _service.SendNotification("Instructor", "3", "John Smith", EntityOperation.DELETE);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor 'John Smith' has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        // Act
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_NoUserName_DefaultsToSystem()
    {
        // Act
        _service.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Act
        var notification = _service.ReceiveNotification();

        // Assert
        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_MultipleNotifications_ReturnsFIFOOrder()
    {
        // Arrange
        _service.SendNotification("First", "1", "First", EntityOperation.CREATE);
        _service.SendNotification("Second", "2", "Second", EntityOperation.UPDATE);
        _service.SendNotification("Third", "3", "Third", EntityOperation.DELETE);

        // Act & Assert
        var first = _service.ReceiveNotification();
        Assert.Equal("First", first!.EntityType);

        var second = _service.ReceiveNotification();
        Assert.Equal("Second", second!.EntityType);

        var third = _service.ReceiveNotification();
        Assert.Equal("Third", third!.EntityType);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        // Arrange
        var before = DateTime.Now;

        // Act
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        // Assert
        var after = DateTime.Now;
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // Act & Assert - no-op method should not throw
        var ex = Record.Exception(() => _service.MarkAsRead(1));
        Assert.Null(ex);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        // Act & Assert
        var ex = Record.Exception(() => _service.Dispose());
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UpdateOperation_UsesIdFormat()
    {
        // Act
        _service.SendNotification("Course", "100", EntityOperation.UPDATE);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course (ID: 100) has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_DeleteOperation_UsesIdFormat()
    {
        // Act
        _service.SendNotification("Student", "50", EntityOperation.DELETE);

        // Assert
        var notification = _service.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student (ID: 50) has been deleted", notification.Message);
    }
}

